arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Pricing && cat > tests/CheckoutPricing.UnitTests/Pricing/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysFiftyFive()
    {
        var types = typeof(ApplicationMarker).Assembly.GetTypes()
            .Concat(typeof(DomainMarker).Assembly.GetTypes())
            .Where(t => t.Name.Contains("Checkout") || t.Name.Contains("Pricing") || t.Name.Contains("Discount"));

        Assert.True(types.Any(), "No checkout/pricing/discount behavior exists; payable total 95.00 for Gold at 100.00 cannot be produced.");
    }
}
E
sed -i 's/PaysFiftyFive/Pays95/' tests/*/Pricing/*.cs
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -15

